package org.mockito.internal.util.reflection;

import java.io.*;
import java.lang.reflect.Field;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class GenericMaster_getGenericType_TriageGen1Test {

    private final GenericMaster genericMaster = new GenericMaster();

    @Test
    public void testGetGenericType_WithParameterizedType() throws NoSuchFieldException {
        // Arrange
        Field field = TestClass.class.getDeclaredField("genericList");
        // TestClass.genericList is List<String>, so getGenericType should return String.class

        // Act
        Class result = genericMaster.getGenericType(field);

        // Assert
        assertEquals(String.class, result);
    }







    // Helper classes for reflection tests
    private static class TestClass {
        java.util.List<String> genericList;
        String simpleString;
        java.util.List rawList;
    }
}

